      }
    ],
    "patient_family_realworld_adaptation": [
      {
        "event_id": "lite_evt_00496",
        "explanation": "Doctor provides plain-language, actionable instructions tailored to a caregiver with partial health literacy, including what to bring to follow-up and how to handle transport barriers.",
        "quote": "把出院小结、CT报告、化验结果、用药清单和血糖记录都带上"
      }
    ]
  },
  "dimension_ratings": {
